 useEffect(()=>{if(['/momento','/momento/comprension','/constelacion','/retorno','/vivir'].includes(location.pathname))history.replaceState({lumenScene:'inicio'},'','/');const change=()=>setOnline(navigator.onLine);window.addEventListener('online',change);window.addEventListener('offline',change);const pop=()=>{const saved=history.state?.lumenScene as Scene|undefined;if(saved&&Object.hasOwn(routes,saved)){sceneTrail.current.pop();setScene(saved);return}const s=Object.entries(routes).find(([,path])=>path===location.pathname)?.[0] as Scene|undefined;if(s&&['inicio','mapa','explorar','santuario','tejido','faro','aprender','ajustes','territorio'].includes(s))setScene(s);else setScene('inicio')};window.addEventListener('popstate',pop);return()=>{window.removeEventListener('online',change);window.removeEventListener('offline',change);window.removeEventListener('popstate',pop)}} ,[])
